const OFFICIAL_TIA_TEMPLATES = JSON.parse(zlib.gunzipSync(
    Buffer.from(OFFICIAL_TIA_CATALOG_GZIP, 'base64')
).toString('utf8'));

// Curated executable rules derived from TIA_V21_报错原文_中英对照.tsv.
// Keeping DLL/KEY provenance makes each translation auditable without making
// the packaged application depend on the collaboration workspace at runtime.
const CURATED_TIA_RULES = [
    {
        dll: 'DataExchange',
        key: 'Feedback.MissingIdentifierAttributes',
        pattern: /Missing ['"]([^'"]+)['"] identifier attribute from the ['"]([^'"]+)['"] object/i,
        explain(match) {
            return `SimaticML 的 ${match[2]} 对象缺少必填标识属性 ${match[1]}；通常是生成器漏写属性，或模板版本与当前博途不一致。`;
        },
    },
    {
        dll: 'BlockLogic',
        key: 'Openness_FeedBack_MissingUID',
        pattern: /The ['"]Access['"] must contain a UID/i,
        explain: () => 'Access 对象缺少 UID，网络中的引用无法关联到对应元件。',
    },
    {
        dll: 'BlockLogic',
        key: 'Openness_FeedBack_NotEnoughConnection',
        pattern: /A rung must have at least two connections/i,
        explain: () => '该梯级连接数不足，需检查电源轨、指令引脚和导线端点是否形成完整网络。',
    },
    {
        dll: 'BlockLogic',
        key: 'Openness_FeedBack_InstructionNotFound',
        pattern: /Cannot find an instruction with name/i,
        explain: () => '当前博途版本找不到该指令或版本，需核对指令名称、版本及目标 CPU 能力。',
    },
    {
        dll: 'BlockLogic',
        key: 'BL_TYPE_MATCH',
        pattern: /(?:Compiler information:\s*)?Type conflict/i,
        explain: () => '指令两侧的数据类型不兼容。',
    },
];

const PART_LABELS = {
    O: '并联块',
    A: '串联块',
    Contact: '触点',
    Coil: '线圈',
};

const escapeRegex = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const OFFICIAL_TIA_MATCHERS = OFFICIAL_TIA_TEMPLATES.map((template) => {
    const source = template.en || template.zh;
    if (!source || source.length < 12) return null;
    const placeholders = [];
    const pattern = source.split(/(\{\d+(?::[^}]*)?\})/).map(part => {
        const placeholder = /^\{(\d+)(?::[^}]*)?\}$/.exec(part);
        if (!placeholder) return escapeRegex(part);
        placeholders.push(Number(placeholder[1]));
        return '(.+?)';
    }).join('');
    return { template, pattern: new RegExp(pattern, 'i'), placeholders };
}).filter(Boolean);

function combinedText(message, stderr) {
    const detail = Array.isArray(stderr) ? stderr.join('\n') : String(stderr || '');
    return [String(message || ''), detail].filter(Boolean).join('\n');
}

function baseHint(overrides) {
    return {
        category: 'tia',
        title: '博途操作失败',
        rootCause: '未识别的博途错误，现有信息不足以可靠判断根因。',
        nextStep: '请导出一键诊断包，并将本次错误详情一并交给管理员分析。',
        ...overrides,
    };
}

function extractUidComponent(xml, uid) {
    if (!xml || !uid) return '';
    const tags = String(xml).match(/<(?:Part|Access)\b[^>]*>/gi) || [];
    const tag = tags.find(item => new RegExp(`\\bUId\\s*=\\s*["']${uid}["']`, 'i').test(item));
    if (!tag) return `UID ${uid}`;
    const type = /^<(Part|Access)\b/i.exec(tag)?.[1] || 'Object';
    const name = /\bName\s*=\s*["']([^"']+)["']/i.exec(tag)?.[1] || '';
    if (!name) return `UID ${uid} = ${type}`;
    const label = PART_LABELS[name];
    return `UID ${uid} = ${type} Name="${name}"${label ? `（${label}）` : ''}`;
}

function officialTemplateHint(text) {
    for (const template of CURATED_TIA_RULES) {
        const match = template.pattern.exec(text);
        if (!match) continue;
        return {
            sourceDll: template.dll,
            sourceKey: template.key,
            rootCause: template.explain(match),
        };
    }

    for (const { template, pattern, placeholders } of OFFICIAL_TIA_MATCHERS) {
        const match = pattern.exec(text);
        if (!match) continue;

        const values = new Map(placeholders.map((index, position) => [index, match[position + 1]]));
        const translated = String(template.zh || '').replace(/\{(\d+)(?::[^}]*)?\}/g,
            (placeholder, index) => values.get(Number(index)) || placeholder);
        return {
            sourceDll: template.dll,
            sourceKey: template.key,
            rootCause: translated && translated !== template.en
                ? translated
                : `博途官方资源未提供中文翻译：${template.en}`,
        };
    }
    return null;
}

function explainTiaError(message, stderr, options = {}) {
    const text = combinedText(message, stderr);
    const official = officialTemplateHint(text);
    const uid = /at the object with UID\s*["']?(\d+)["']?/i.exec(text)?.[1];
    if (uid) {
        return baseHint({
            ...official,
            layer: 'network',
            uid,
            component: extractUidComponent(options.xml, uid),
            title: `梯形图内部接线或指令有误（元件 #${uid}）`,
            rootCause: official?.rootCause || '网络对象的连接、指令参数或引用关系不符合博途语义规则。',
            nextStep: '按元件名称定位到对应 Part/Access，检查该元件的引脚、导线和指令参数。',
        });
    }

    if (/Invalid XML/i.test(text)) {
        return baseHint({
            layer: 'xml',
            title: '生成的文件格式有误',
            rootCause: 'XML 文档本身无法解析，尚未进入 SimaticML 对象校验。',
            nextStep: '先检查 XML 是否完整、标签是否闭合，以及特殊字符是否正确转义。',
        });
    }

    const lineNumber = /line number\s+(\d+)/i.exec(text)?.[1];
    if (lineNumber || /line position\s+\d+/i.test(text)) {
        return baseHint({
            ...official,
            layer: 'simaticml',
            lineNumber: lineNumber ? Number(lineNumber) : null,
            title: `块结构/版本/属性/语言有问题${lineNumber ? `（第 ${lineNumber} 行）` : ''}`,
            rootCause: official?.rootCause || 'XML 可解析，但 SimaticML 对象的结构、属性或版本不符合导入规则。',
            nextStep: `检查${lineNumber ? `第 ${lineNumber} 行附近的` : ''}对象属性、语言标记和目标博途版本。`,
        });
    }

    if (/[\uE000-\uF8FF]/u.test(text)) {
        return baseHint({
            category: 'encoding',
            title: '检测到不可逆的中文编码错读',
            rootCause: '标识符在编码源头被错误解码，并已出现私用区字符。',
            nextStep: '必须从源头改编码并重新生成文件；字节长度已经变化，不能自动修复现有乱码。',
        });
    }

    if (/(?:Type conflict|Data type .+ cannot be converted implicitly)/i.test(text)) {
        return baseHint({
            ...official,
            category: 'type',
            title: '数据类型不匹配',
            rootCause: official?.rootCause || '操作数或赋值两侧的数据类型不兼容。',
            nextStep: '请先确认该块的「IEC 检查」属性（块属性 → 常规），开启与关闭时编译规则不同；再核对实际类型转换。',
        });
    }

    if (/Could not find TIA Portal installation path/i.test(text)) {
        return baseHint({
            title: '未找到博途安装信息',
            rootCause: '注册表里找不到博途安装信息，程序无法定位 Openness 组件。',
            nextStep: '确认已安装博途并勾选 Openness 选件，然后运行一键诊断。',
        });
    }
    if (/net48 dir missing/i.test(text)) {
        return baseHint({
            title: '未找到 Openness 程序集目录',
            rootCause: '博途可能安装在非默认路径，默认 net48 目录不存在。',
            nextStep: '运行一键诊断获取实际路径，并核对对应版本的 PublicAPI/net48 目录。',
        });
    }
    if (/Could not find DLL ['"]Siemens\.Engineering\.WinCCUnified/i.test(text)) {
        return baseHint({
            title: 'WinCC Unified 组件缺失',
            rootCause: 'WinCC Unified 的 Openness 组件不完整或未安装。',
            nextStep: '打开博途安装程序，补装 WinCC Unified 的 Openness 支持。',
        });
    }
    if (/(?:EngineeringSecurityException|access denied|permission|AllowList)/i.test(text)) {
        return baseHint({
            title: '博途拒绝了本程序的访问',
            rootCause: '当前用户未获 Siemens TIA Openness 用户组权限，或程序路径未进入 Openness AllowList。',
            nextStep: '由管理员执行 `net localgroup "Siemens TIA Openness" "%USERNAME%" /add`，注销并重新登录；绿色版更换目录后还需在博途中重新授权当前程序路径。',
        });
    }
    if (/请求超时/i.test(text) && /Checking Windows group membership/i.test(text)) {
        return baseHint({
            title: '组成员检查被阻塞',
            rootCause: '无窗口子进程触发的 UAC 授权框可能不可见，导致连接一直等待。',
            nextStep: '请管理员手动把当前用户加入 Siemens TIA Openness 组，注销重新登录后重试。',
        });
    }
    if (/子进程退出\(code=1/i.test(String(message || '')) && !String(Array.isArray(stderr) ? stderr.join('') : stderr || '').trim()) {
        return baseHint({
            title: 'TIA 子进程被异常终止',
            rootCause: '没有任何 stderr，极可能被杀毒软件或终端管控直接拦截。',
            nextStep: '请将程序目录加入安全软件白名单后重试，并导出诊断包供管理员确认。',
        });
    }
    if (/no project is open/i.test(text)) {
        return baseHint({
            title: '博途没有打开工程',
            rootCause: 'TIA Portal 正在运行，但当前确实没有打开工程。',
            nextStep: '打开博途并打开一个工程，然后重新连接。',
        });
    }
    if (/(?:0x80131509|FileLoadException)/i.test(text)) {
        return baseHint({
            title: 'Openness 程序集加载失败',
            rootCause: '程序集加载失败，多为运行时与已安装博途版本不匹配。',
            nextStep: '运行一键诊断核对博途版本与当前引擎版本，再选择匹配版本。',
        });
    }
    if (/(?:Zone\.Identifier|LoadFrom)/i.test(text)) {
        return baseHint({
            title: 'Windows 阻止了程序集加载',
            rootCause: 'ZIP 下载后的文件带有 Internet 区域标记，Windows 阻止加载。',
            nextStep: '在 ZIP 或文件属性中选择「解除锁定」，或由管理员运行 `Unblock-File` 后重新解压。',
        });
    }

    return baseHint(official || {});
}

module.exports = { explainTiaError, OFFICIAL_TIA_TEMPLATES };
